  "postV1ProjectsByProjectIdArtifactsOptimistic-eval-tests": {
    parameters: {
      query?: never;
      header?: never;
      path: {
        projectId: string;
      };
      cookie?: never;
    };
    requestBody: {
      content: {
        "application/json": {
          /** @description The historical trace to extract evidence from */
          trace_id: string;
          /** @description A complete JavaScript function expression: async ({ traceId, sql }) => { ... }. Return JSON evidence; throw when validation fails. */
          source_code: string;
          /**
           * Format: uuid
           * @description The judge in this project
           */
          judge_id: string;
          /**
           * Format: uuid
           * @description The exact judge version ID returned by get_judge
           */
          judge_version_id: string;
        };
      };
    };
    responses: {
      /** @description Response for status 200 */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": {
            /** Format: uuid */
            judge_id: string;
            /** Format: uuid */
            judge_version_id: string;
            judge_major_version: number;
            judge_minor_version: number;
            /** @enum {string} */
            score_type: "binary" | "categorical";
            trace_id: string;
            result:
              | {
                  /** @enum {string} */
                  status: "accepted";
                  verdict: boolean | string;
                  /** @enum {string|null} */
                  reason: null;
                  /** @enum {string|null} */
                  error: null;
                  confidence: number;
                  duration_ms: number;
                  artifact_duration_ms: number;
                  evidence_size_bytes: number;
                }
              | {
                  /** @enum {string} */
                  status: "fallback";
                  /** @enum {string|null} */
                  verdict: null;
                  /** @enum {string} */
                  reason:
                    | "artifact_failed"
                    | "evidence_and_rubric_too_large"
                    | "model_failed"
                    | "low_confidence"
                    | "timeout";
                  /** @enum {string|null} */
                  error: null;
                  confidence: number | null;
                  duration_ms: number;
                  artifact_duration_ms: number | null;
                  evidence_size_bytes: number | null;
                }
              | {
                  /** @enum {string} */
                  status: "failed";
                  /** @enum {string|null} */
                  verdict: null;
                  /** @enum {string|null} */
                  reason: null;
                  error: string;
                  /** @enum {string|null} */
                  confidence: null;
                  duration_ms: number;
                  /** @enum {string|null} */
                  artifact_duration_ms: null;
                  /** @enum {string|null} */
                  evidence_size_bytes: null;
                };
            ordinary_agent:
              | {
                  /** @enum {string} */
                  status: "completed";
                  verdict: boolean | string;
                  reason: string;
                  /** @enum {string|null} */
                  error: null;
                  duration_ms: number;
                }
              | {
                  /** @enum {string} */
                  status: "failed";
                  /** @enum {string|null} */
                  verdict: null;
                  /** @enum {string|null} */
                  reason: null;
                  error: string;
                  duration_ms: number;
                };
            matches: boolean | null;
          };
        };
      };
    };
  };
