  postV1ProjectsByProjectIdAutomations: {
    parameters: {
      query?: never;
      header?: never;
      path: {
        projectId: string;
      };
      cookie?: never;
    };
    requestBody: {
      content: {
        "application/json": {
          name: string;
          description?: string;
          /** @description Required scope: [] for all environments; [""] for traces without an environment. */
          environment_names: string[];
          conditions: ({
            metric: {
              /** @enum {string} */
              scorer_type:
                | "static"
                | "prompt"
                | "custom"
                | "judge"
                | "behavior"
                | "span_attribute"
                | "error";
              name: string;
              threshold?: number | string | null;
            } & {
              [key: string]: unknown;
            };
            /** @enum {string} */
            comparison:
              | "lt"
              | "gt"
              | "eq"
              | "gte"
              | "lte"
              | "chooses"
              | "detected"
              | "equals"
              | "notEquals"
              | "contains"
              | "doesNotContain"
              | "exists";
          } & {
            [key: string]: unknown;
          })[];
          /** @enum {string} */
          combine_type: "all" | "any";
          actions?: {
            dataset_addition?:
              | ({
                  enabled?: boolean;
                  dataset_name: string;
                  metadata_fields?: unknown;
                } & {
                  [key: string]: unknown;
                })
              | null;
            notification?:
              | ({
                  enabled?: boolean;
                  communication_methods: (
                    | "email"
                    | "slack"
                    | "pagerduty"
                    | "webhook"
                  )[];
                  email_addresses?: string[];
                  slack_channels?: string[];
                  pagerduty_config?:
                    | ({
                        routing_key: string;
                        /** @enum {string} */
                        severity?: "critical" | "error" | "warning" | "info";
                      } & {
                        [key: string]: unknown;
                      })
                    | null;
                  webhook_config?:
                    | ({
                        /** Format: uri */
                        url: string;
                        secret: string;
                      } & {
                        [key: string]: unknown;
                      })
                    | null;
                  send_at?: number | null;
                } & {
                  [key: string]: unknown;
                })
              | null;
            behavior_evaluation?:
              | ({
                  enabled?: boolean;
                  behavior_judge_names: string[];
                  sampling_rate?: number;
                } & {
                  [key: string]: unknown;
                })
              | null;
          } & {
            [key: string]: unknown;
          };
          /** @description Cooldown period; both value and unit are required. */
          cooldown_period?: {
            value: number;
            /** @enum {string} */
            unit: "seconds" | "minutes" | "hours" | "days";
          };
          /** @description Trigger frequency; count, period, and period_unit are all required. */
          trigger_frequency?: {
            count: number;
            period: number;
            /** @enum {string} */
            period_unit: "seconds" | "minutes" | "hours" | "days";
          };
        };
      };
    };
    responses: {
      /** @description Response for status 200 */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          "application/json": {
            rule_id: string;
          };
        };
      };
    };
  };
